import pathlib,json,hashlib,datetime,re
L=pathlib.Path(__file__).resolve().parent;C=L.parent
r=json.loads((L/'literal-records.json').read_text())
notes={
'330839':('PARK_WORDING_AND_ROOT_LOCATION','Conjecture 7, Section 4; recurrence (9), formula (12).','T2/x=1+x+x^2 already has real parts -1/2. The source explicitly allows nonzero real parts in its conjugate-root definition: imaginary means nonreal here. Pure-imaginary refutation is an ineligible wording correction. Need nonreal roots plus simultaneous real/imaginary separation for every n. No all-n root-location argument obtained.'),
'330887':('EXCLUDE_SOURCE_OWN_TESTED_SCOPE','Conjecture 2, CCC subsection; definition of s-truncated embedding.','Literal MathDB confines to n=3,4,5, precisely the source-tested data. General n is the actual source conjecture. Rechecking these cases reproduces source data; extending to n=6 is not a full source resolution nor required by this literal record. No new witness proposed.'),
'330932':('PARK_HARD_STRUCTURAL','Conjecture 1 following Theorem 6.2.','Must find one ergodic full-group element whose cyclic subrelation has a treeing extending to the entire relation. Cost >1 alone does not construct this primitive element. No measurable selection or treeing-extension lemma established; finite permutations cannot certify it.'),
'331005':('PARK_HOMOTOPY','Section 7, Conjecture 7.1 and Proposition 7.2.','Permanent-cycle statement is for the paper-specific normed bordism slice spectral sequence, not any spectral sequence for the group. Proposition 7.2 only handles other representation classes. Need an actual higher-n differential or proof excluding every differential; no such calculation performed. The source itself warns the statement may be too strong.'),
'331097':('ORDINARY_PROOF_ROUTINE_SIGNIFICANCE_HOLD','Definition 2, Conjecture 13; Theorem 6 principal-ideal proof.','ATTEMPTS.md gives the full divisor-truncation representative proof and the immediate adjacency bridge. No missing ordinary algebraic lemma under source definitions; missing latest published-body/prior-art qualification, significance ruling, and all Lean work. Recommend no execution until root determines this is more than an excluded routine annihilator bridge.'),
'331254':('PARK_BASIS','Definitions 2.12 and 2.15; Conjecture 2.20.','Equivalence classes must be deduplicated by their generating functions, since the conjecture concerns a set of functions. A finite dependence certificate would need distinct class polynomials, their exact fundamental-basis vectors, and integer dependence. Source verified through degree 11; full permutation enumeration above that is inappropriate here. No triangularity or distinct-vector dependence found.'),
'331277':('PARK_DUPLICATE_FAMOUS','Conjectures 1.2 and 1.3 distinguish intersecting and adjacent triangles.','Matches historical 328365, fresh-corpus-r7. Strong Bordeaux/Steinberg counterexamples do not resolve the stronger vertex-disjoint-triangle hypothesis. Later 2026 paper identified by search concerns Strong Bordeaux and improper coloring; its journal proof body not read. No graph proposed. Do not reopen as a cleared finite obstruction.'),
'331332':('PARK_CONVEX_SUBDIVISION','Section 2 constructions; Section 4 final subdivision belief in v2, Conjecture 2 in v1.','Preserving convexity after subdividing an existing admissible drawing does not produce an admissible drawing of arbitrary graph topology. Need simultaneous strict supporting lines for every edge midpoint and distinctness of all vertices/midpoints; no universal placement construction found. K2,n and K3,3 subdivisions are printed source controls and cannot earn credit.'),
'331487':('EXCLUDE_SOURCE_PROVED','Conjecture 1.2, Theorems 1.4 and 1.5; Section 4 proof strategy and concluding lemmas.','Source itself proves the fixed-prime finiteness claim. Theorem 1.4 forces r|(q+1), Theorem 1.5 gives finiteness in that range; q<r gives finitely many extra pairs. Section 4 separates finite possible characteristics, excludes infinite q outside {2,3,5}, then treats those three. No new proof claimed; 2026 Wendt-result search hit is unnecessary and its proof body not reviewed.'),
'331498':('EXECUTABLE_COEFFICIENT_CANDIDATE_NO_WITNESS','Source Section 4 Conjecture 4.1; original ABM Section 6.3 P2, N1-N3; later Elvey Price body.','ATTEMPTS.md supplies exact prefix-polynomial recurrence with ordinary soundness proof and certificate format. CANDIDATE.md specifies a bounded Pi task conditional on remaining source gates. Need an actual negative coefficient or all-parameter cancellation proof. All existing printed negative examples change the domain or fix both projections. No endpoint claimed.'),
'331506':('PARK_ANALYTIC','Higher-dimensional Borg discussion in periodic elliptic operator survey, target equivalence.','Entire dispersion branch for a periodic continuous Schrodinger operator is an analytic global assertion. Finite matrix/discrete-potential analogues do not settle it. No proof reducing entire branch to constant potential under exact source hypotheses. Journal and all later spectral literature not cleared.'),
'331664':('PARK_WILF_EQUIVALENCE','Source generalized pattern definitions and Harmse-Remmel conjecture discussion.','Strong implies avoidance by x=0; converse requires recovering every occurrence-count coefficient from all avoidance counts. Finite agreement of avoidance series cannot prove c-Wilf equivalence. A counterexample needs exact all-length avoidance identity plus one differing occurrence count; no such identity found. Nonoverlapping ordinary-permutation theorems do not automatically settle generalized Euler arrays.'),
'331757':('EXCLUDE_REPORTED_KNOWN','Source Introduction Conjecture 1.1 and Section 2 statement attributed to Fox-Pach.','Literal record and source already report proof with 6ek+1 colors. Read source reporting and its surrounding proof discussion; original 2012 Fox-Pach manuscript not independently acquired. Thus exclude as already reported known, without claiming independent verification of Fox-Pach proof body.'),
'331758':('PARK_ADDITIVE_STRING_BOUND','Source Introduction, Section 4 contact-system bounds.','k+5 theorem for straight segments and (4k/3)+6 theorem for contact systems are not the all-string additive bound. Source large-clique examples allow repeated pair intersections; they are not valid 1-intersecting counterexamples. Need a uniform additive proof or family with unbounded chi-k; a single graph with chi>k is insufficient.'),
'331779':('PARK_LOCAL_DYNAMICS','Source Sections 1-3, Conjecture 1 and Figures 1-7.','Valuation absolute-difference bridge and missing confinement lemma recorded in ATTEMPTS.md. Connectivity and threshold semantics must be resolved before any finite component certificate. Source proves p=2; odd p is not covered. No search or witness.'),
'331780':('PARK_LEFT_EDGE_DYNAMICS','Source Section 1 Conjecture 2 and Section 3 2-tomography.','Exact certificate format: prime p, finite initial valuation vector, all absolute-difference rows, terminal exponent >=2. It would give a literal finite refutation. No such vector obtained. Parity/XOR or squarefree initial-model arguments erase the required high valuation and do not prove full claim.'),
'331785':('PARK_INFINITE_OBSTRUCTIONS','Source Section 5 Conjecture 5.1, preceding tournament constructions.','Fixed-numbering Postnikov-Stanley forbidden cycles are not forbidden induced tournaments after allowing arbitrary renumbering. A single non-semiacyclic tournament does not refute finiteness. Need an infinite pairwise nonisomorphic vertex-minimal family or size bound for all minimal obstructions. No route beyond known source examples.'),
'331786':('PARK_INFINITE_OBSTRUCTIONS','Source Section 5 Conjecture 5.2 and two-type coin characterizations.','Nine- and 81-vertex constructions in source are printed examples, not new witnesses, and even a new nonrepresentable tournament cannot refute finite-obstruction existence. Need an infinite minimal family and proof under all real coin parameters. No such family obtained; no feasibility sweep justified.'),
'331825':('EXCLUDE_PUBLISHED_EXACT_PROOF','Source Conjecture 4.14; Yan-Zhou DMTCS 2017 Conjecture 1.2 and Section 6 proof.','Read exact matching polynomial formula and final proof using type B linked partitions, formulas (6.4),(6.12),(6.16),(6.17), with Ln=(x+1)^(n-1). Thus excluded by an actual journal proof body, not just the abstract or unweighted-corner theorem. n<3 wording endpoint issues do not receive credit.'),
'331959':('PARK_SPECTRAL_RATIO','Source Conjecture 3.1 and surface table.','P<= is an upper-bound regime, not a lower bound. Excluding exponential convergence requires a uniform lower separation theorem for all pseudo-Anosov mapping classes on those surfaces; exhibited polynomial families cannot prove it. No such lower bound supplied; not a finite certificate target.')}
out={}
for i,v in r.items():
 status,body,gap=notes[i]; rec=v['record']; a=rec['source_url'].split('/')[-1]
 out[i]={'mathdb_id':int(i),'title':rec['title'],'statement_literal':rec['statement'],'canonical_url':rec.get('canonical_url'),'source_url':rec['source_url'],'provenance':v['provenance'],'raw_record_file':i+'.raw.jsonl','disposition':status,'review_depth':{'literal_record_read':True,'latest_primary_pdf_acquired':True,'earlier_arxiv_versions_acquired':True,'inspected_primary_loci':body,'full_all_version_proof_audit':False,'journal_and_errata_clearance':'Exact 331825 later journal proof read; otherwise not comprehensively cleared. See SOURCE-REVIEW.md.','source_example_inventory':'No witness proposed. Textual P2 negative-example inventory in ATTEMPTS.md; complete figure inventory not claimed.'},'mathematical_attempt_and_precise_gap':gap,'prior_status':{'assigned_by_existing_reserve8':True,'absence_from_indexes_is_novelty':False,'history':'Bordeaux duplicate 328365; Stirling related exclusion 346486; routine/source-own/protected family precedents retained. See relevant-history.json and SOURCE-REVIEW.md.','public_screen':'Fresh HEAD and raw candidates/projects acquired. Complete relevant subtree and body-screen limits in SOURCE-REVIEW.md. No global novelty clearance.','novelty_cleared':False},'ordinary_proof_complete':i=='331097','executable_next_pi_task':'CANDIDATE.md' if i=='331498' else None,'full_lean_endpoint':False,'accepted_credit':0,'receipts':[a+'-pdf.receipt.json',a+'-abs.receipt.json']}
assert len(out)==20 and set(map(int,out))==set(json.loads((L/'reservation.json').read_text())['ids'])
(L/'results.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')
# Disjointness and unchanged reservation, without regenerating or editing shared reservations.
ids=set(map(int,out)); overlaps=[]
for p in C.glob('*/reservation.json'):
 if p.parent==L:continue
 try:common=ids & set(json.loads(p.read_text()).get('ids',[]))
 except:continue
 if common:overlaps.append({'file':str(p),'ids':sorted(common)})
(L/'reservation-validation.json').write_text(json.dumps({'checked_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'count':20,'other_reservation_intersections':overlaps,'selection':'Existing root-issued reserve8 reservation retained, not rerun against changed indexes.','limitation':'Reserve8 input hashes are historical; absence from reservations is not novelty.'},indent=2))
